import React, { useState, useEffect } from 'react';
import 'bootstrap/dist/css/bootstrap.min.css';
import 'bootstrap/dist/js/bootstrap.bundle.min';

// ExperienceCard component
const ExperienceCard = ({ title, role, period, description }) => (
    <div className="edu-card rounded-3 border-gradient border-5 p-3 mb-2" style={{ boxShadow: 'rgba(6, 24, 44, 0.4) 0px 0px 0px 2px, rgba(6, 24, 44, 0.65) 0px 4px 6px -1px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset' }}>
        <div className="card-body">
            <div className="d-flex justify-content-between flex-wrap">
                <p className="text-gradient"><b>{title}</b></p>
                <div>
                    <i className="fa-solid fa-calendar-days me-2 text-gradient"></i><span>{period}</span>
                </div>
            </div>
            <h6><b>{role}</b></h6>
            <p className="text-muted">{description}</p>
        </div>
    </div>
);

// Array of experience objects
const experiences = [
    {
        title: 'Self Employed',
        role: 'Web Developer',
        period: 'Mar 2022 - Present',
        description: 'Since starting my journey in web development in March 2022, I have transformed my passion for coding into a professional skill set. As a self-employed developer, I specialize in the MERN Stack and have successfully created over 50 websites that demonstrate my commitment to quality, user experience, and effective functionality. My focus lies in understanding client needs and delivering tailored solutions that enhance online presence.'
    },
    {
        title: 'UNITEDSOL Software Company Islamabad',
        role: 'Web Development Internship',
        period: 'Feb 2022 - Aug 2022',
        description: 'During my 6-month internship at United Sol Software Company Islamabad, I gained hands-on experience with a variety of web technologies including HTML, CSS, JavaScript, jQuery, PHP, and WordPress. This role provided me with the opportunity to work on real-world projects, collaborate with experienced developers, and enhance my problem-solving skills, all of which significantly contributed to my growth as a web developer.'
    },
    {
        title: 'SNIPBYTE Software Company Islamabad',
        role: 'Front End Developer',
        period: 'Nov 2022 - Dec 2023',
        description: 'As a Frontend Developer at Snipbyte since November 2022, I have been dedicated to crafting user-centric interfaces that improve the overall user experience. My expertise in HTML, CSS, Bootstrap, and React.js allows me to bring creative designs to life while ensuring optimal performance. I thrive in collaborative environments, where I actively contribute to projects and push the boundaries of web development through innovative solutions.'
    },
    {
        title: 'ODL Software Company Islamabad',
        role: 'MERN Stack Developer',
        period: 'Jan 2024 - Present',
        description: 'At the beginning of 2024, I joined ODL Software Company as a MERN Stack Developer, focusing on building robust and dynamic web applications. My work involves utilizing the full power of the MERN stack—MongoDB, Express.js, React.js, and Node.js—to develop scalable solutions that meet client demands. I am passionate about leveraging technology to drive innovation and enhance user engagement within my team.'
    }
];

// Main component

const SkillsAndExperience = () => {
    // Initial date for experience
    const startDate = new Date('2022-01-01T00:00:00');
    const [timeElapsed, setTimeElapsed] = useState('');

    const calculateTimeElapsed = () => {
        const now = new Date();
        const totalSeconds = Math.floor((now - startDate) / 1000);
        
        const years = Math.floor(totalSeconds / (365.25 * 24 * 60 * 60));
        const months = Math.floor((totalSeconds % (365.25 * 24 * 60 * 60)) / (30 * 24 * 60 * 60));
        const days = Math.floor((totalSeconds % (30 * 24 * 60 * 60)) / (24 * 60 * 60));
        const hours = Math.floor((totalSeconds % (24 * 60 * 60)) / (60 * 60));
        const minutes = Math.floor((totalSeconds % (60 * 60)) / 60);
        const seconds = totalSeconds % 60;

        // Formatting the time elapsed string
        setTimeElapsed(`${years} years, ${months} months, ${days} days, ${hours} hours, ${minutes} minutes, ${seconds} seconds`);
    };

    useEffect(() => {
        // Calculate time immediately and set interval to update every second
        calculateTimeElapsed();
        const interval = setInterval(calculateTimeElapsed, 1000);
        
        // Cleanup interval on component unmount
        return () => clearInterval(interval);
    }, []);

    return (
        <section id="skillss">
            <div>
                <div className="d-flex gap-3 justify-content-center text-mediumaquamarine mt-3">
                    <span className="h1 text-dark custom-heading" style={{ fontWeight: "800", fontSize: "40px" }}>Experience</span>
                </div>
                <div className="d-flex gap-3 justify-content-center text-mediumaquamarine mt-1">
                    <span className="h1 text-dark  d-none d-md-block" style={{ fontSize: "16px" }}>
                        Jan 2022 - <span className="text-gradient fw-bolder"> Present </span> ( {timeElapsed} )
                    </span>
                    <span className="h1 text-dark  d-md-none" style={{ fontSize: "16px" }}>
                        Jan 2022 - Present
                    </span>
                </div>
                <hr className='mb-5' style={{ height: '5px' }} />
                <div className='container'>
                    {/* Check if the screen width is less than 768px */}
                    <div className="d-md-none">
                        {/* Display cards for mobile devices */}
                        <div className="row">
                            {experiences.map((exp, index) => (
                                <div className='col-12 mb-3' key={index}>
                                    <ExperienceCard
                                        title={exp.title}
                                        role={exp.role}
                                        period={exp.period}
                                        description={exp.description}
                                    />
                                </div>
                            ))}
                        </div>
                    </div>
                    <div className="d-none d-md-block">
                        {/* Display carousel for larger screens */}
                        <div id="experienceCarousel" className="carousel slide" data-bs-ride="false"> {/* Disable auto slide */}
                            <div className="carousel-inner">
                                {experiences.map((exp, index) => (
                                    <div className={`carousel-item ${index === 0 ? 'active' : ''}`} key={index}>
                                        <div className="row justify-content-center">
                                            <div className='col-md-6'>
                                                <ExperienceCard
                                                    title={exp.title}
                                                    role={exp.role}
                                                    period={exp.period}
                                                    description={exp.description}
                                                />
                                            </div>
                                        </div>
                                    </div>
                                ))}
                            </div>
                            {/* Show Next and Prev buttons */}
                            <button className="carousel-control-prev bg-custom" type="button" data-bs-target="#experienceCarousel" data-bs-slide="prev">
                                <span className="carousel-control-prev-icon" aria-hidden="true"></span>
                                <span className="visually-hidden">Previous</span>
                            </button>
                            <button className="carousel-control-next bg-custom" type="button" data-bs-target="#experienceCarousel" data-bs-slide="next">
                                <span className="carousel-control-next-icon" aria-hidden="true"></span>
                                <span className="visually-hidden">Next</span>
                            </button>
                        </div>
                    </div>
                </div>
            </div>
            <br />
            <div className='d-flex w-100 justify-content-start align-items-center'>
                <div style={{ width: "100%", height: "2px" }} className='bg-custom mt-3'></div>
            </div>
        </section>
    );
};



export default SkillsAndExperience;
