
import { useState, useEffect } from 'react';
// Skill component

const Skill = ({ heading, icon, color }) => {
    const [bgColor, setBgColor] = useState(''); // State for background color

    // Function to generate a random RGB color
    const getRandomColor = () => {
        const randomColor = () => Math.floor(Math.random() * 256);
        return `rgb(${randomColor()}, ${randomColor()}, ${randomColor()})`;
    };

    // Function to handle mouse over
    const handleMouseOver = () => {
        const color1 = getRandomColor();
        const color2 = getRandomColor();
        setBgColor(`linear-gradient(135deg, ${color1}, ${color2})`);
    };

    // Function to handle mouse out
    const handleMouseOut = () => {
        setBgColor(''); // Reset background color
    };

    return (
        <div
            className="p-4 w-100 bg-white text-center rounded border d-flex flex-column justify-content-center align-items-center"
            style={{
                width: '10rem',
                height: '10rem',
                boxShadow: 'rgba(6, 24, 44, 0.4) 0px 0px 0px 2px, rgba(6, 24, 44, 0.65) 0px 4px 6px -1px, rgba(255, 255, 255, 0.08) 0px 1px 0px inset',
                background: bgColor, // Apply dynamic background color
                transition: 'background 0.3s ease, transform 0.3s ease',
                transform: bgColor ? 'scale(1.05)' : 'scale(1)', // Scale on hover
            }}
            onMouseOver={handleMouseOver}
            onMouseOut={handleMouseOut}
        >
            <i className={`fa ${icon} mx-auto h1`} style={{ color: `${color}` }}></i>
            <h6 className="text-dark h5">{heading}</h6>
        </div>
    );
};




// Array of skill objects with specific icon colors
const skills = [
    { heading: 'HTML', icon: 'fa-brands fa-html5', color: '#E34F26' },
    { heading: 'CSS', icon: 'fa-brands fa-css3-alt', color: '#1572B6' },
    { heading: 'Bootstrap', icon: 'fa-brands fa-bootstrap', color: '#563d7c' },
    { heading: 'ReactJs', icon: 'fa-brands fa-react', color: '#61DAFB' },
    { heading: 'JavaScript', icon: 'fa-brands fa-js', color: '#f0db4f' },
    { heading: 'jQuery', icon: 'fa-solid fa-file-code', color: '#0769AD' },
    { heading: 'NodeJs', icon: 'fa-brands fa-node-js', color: '#68A063' },
    { heading: ' NextJs', icon: 'fa-solid fa-question', color: '#21759B' },
    { heading: 'WordPress', icon: 'fa-brands fa-wordpress', color: '#21759B' },
];



const Skills = () => {
  const [displayedSkills, setDisplayedSkills] = useState([]);

  useEffect(() => {
    skills.forEach((skill, index) => {
      setTimeout(() => {
        setDisplayedSkills((prev) => [...prev, skill]);
      }, index * 300); // 2 seconds delay for each card
    });
  }, []);

  return (
    <section id="skillss">
      <div className="row">
        <div className="col-12 col-lg-12 col-md-12 col-sm-12">
          <div>
            <div className="d-flex gap-3 justify-content-center text-mediumaquamarine py-3">
              <span
                className="h1 text-dark custom-heading"
                style={{ fontWeight: "800", fontSize: "40px" }}
              >
                Skills
              </span>
            </div>
            <hr style={{ height: '2px' }} />

            <div className="d-flex flex-wrap gap-3 justify-content-center p-1 p-md-2 px-4 container">
              <div className="row container">
                {displayedSkills.map((skill, index) => (
                  <div
                    key={index}
                    className="col-md-2 col-12 mb-4 custom-portfolio-card"
                  >
                    <Skill
                      heading={skill.heading}
                      icon={skill.icon}
                      color={skill.color}
                      imgSrc={skill.imgSrc}
                    />
                  </div>
                ))}
              </div>
            </div>
            <div className="d-flex w-100 justify-content-start align-items-center">
              <div
                style={{ width: "100%", height: "2px" }}
                className="bg-custom mt-3"
              ></div>
            </div>
          </div>
        </div>
      </div>
    </section>
  );
};

export default Skills;
